DROP PROCEDURE IF EXISTS `sp_users_create`$$

CREATE PROCEDURE `sp_users_create`(
    IN p_id CHAR(36),
    IN p_phone TEXT,
    IN p_email TEXT,
    IN p_full_name TEXT,
    IN p_password_hash TEXT,
    IN p_avatar_url TEXT,
    IN p_status VARCHAR(20),
    IN p_created_by CHAR(36),
    IN p_updated_by CHAR(36),
    IN p_deleted_at DATETIME
)
BEGIN
    IF p_id IS NULL OR p_id = '' THEN SET p_id = UUID(); END IF;
    INSERT INTO `users` (`id`, `phone`, `email`, `full_name`, `password_hash`, `avatar_url`, `status`, `created_by`, `updated_by`, `deleted_at`)
    VALUES (p_id, p_phone, p_email, p_full_name, p_password_hash, p_avatar_url, p_status, p_created_by, p_updated_by, p_deleted_at);
    SELECT * FROM `users` WHERE `id` = p_id;
END$$

DROP PROCEDURE IF EXISTS `sp_users_get`$$

CREATE PROCEDURE `sp_users_get`(IN p_id CHAR(36))
BEGIN
    SELECT * FROM `users` WHERE `id` = p_id;
END$$

DROP PROCEDURE IF EXISTS `sp_users_list`$$

CREATE PROCEDURE `sp_users_list`(IN p_limit INT, IN p_offset INT)
BEGIN
    IF p_limit IS NULL OR p_limit <= 0 THEN SET p_limit = 50; END IF;
    IF p_offset IS NULL OR p_offset < 0 THEN SET p_offset = 0; END IF;
    SELECT * FROM `users` WHERE `deleted_at` IS NULL ORDER BY `created_at` DESC LIMIT p_limit OFFSET p_offset;
END$$

